 static final int INK=Color.rgb(24,53,47),GREEN=Color.rgb(33,78,61),MUTED=Color.rgb(101,118,108),PAPER=Color.rgb(245,246,241),LIME=Color.rgb(221,249,154),LINE=Color.rgb(225,230,221);
 LinearLayout root,content,bottom;JSONArray apps=new JSONArray();boolean loading=false,showingDetail=false;int selected=0;String networkError="";JSONObject pendingInstall;boolean invitationOpen=false;
 int dp(float v){return (int)(getResources().getDisplayMetrics().density*v+.5f);}
 GradientDrawable background(int color,int radius,boolean border){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));if(border)d.setStroke(dp(1),LINE);return d;}
 TextView text(String value,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setLineSpacing(dp(3),1);t.setFontFeatureSettings("kern");if(bold)t.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));return t;}
 LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
 void gap(LinearLayout l,int height){View v=new View(this);l.addView(v,new LinearLayout.LayoutParams(1,dp(height)));}
 void pad(View v,int all){v.setPadding(dp(all),dp(all),dp(all),dp(all));}
 Button button(String label,boolean primary,Runnable action){Button b=new Button(this);b.setText(label);b.setTextSize(14);b.setAllCaps(false);b.setTextColor(primary?Color.WHITE:GREEN);b.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));b.setBackground(background(primary?GREEN:Color.WHITE,13,!primary));b.setMinHeight(dp(49));b.setPadding(dp(17),dp(7),dp(17),dp(7));b.setOnClickListener(v->action.run());return b;}
 void full(LinearLayout l,View v){l.addView(v,new LinearLayout.LayoutParams(-1,-2));}
 TextView badge(String label,boolean warning){TextView b=text(label,11,warning?Color.rgb(128,93,39):GREEN,true);b.setPadding(dp(10),dp(5),dp(10),dp(5));b.setBackground(background(warning?Color.rgb(255,242,221):Color.rgb(235,242,225),8,false));return b;}
