 void alert(String title,String message){if(!isFinishing())new AlertDialog.Builder(this).setTitle(title).setMessage(message).setPositiveButton("C’est compris",null).show();}
 boolean demo(){return !Access.connected(this);}
 @Override public void onCreate(Bundle saved){super.onCreate(saved);getWindow().setStatusBarColor(PAPER);getWindow().setNavigationBarColor(PAPER);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);for(File f:getCacheDir().listFiles()==null?new File[0]:getCacheDir().listFiles())if(f.getName().startsWith("cercle-")&&System.currentTimeMillis()-f.lastModified()>86400000L)f.delete();loadCached();if(getIntent().getBooleanExtra("updates",false))selected=1;render();handleIntent(getIntent());if(!demo())refresh(false);}
 @Override public void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);if(intent.getBooleanExtra("updates",false)){selected=1;render();}handleIntent(intent);}
 @Override public void onResume(){super.onResume();if(root!=null&&pendingInstall!=null&&getPackageManager().canRequestPackageInstalls()){JSONObject app=pendingInstall;pendingInstall=null;root.postDelayed(()->download(app),200);}if(root!=null&&!showingDetail&&!invitationOpen)render();if(!demo())UpdateJob.schedule(this);}
 void loadCached(){if(demo()){apps=examples();return;}JSONObject cached=Api.cached(this);if(cached!=null)apps=cached.optJSONArray("apps");if(apps==null)apps=new JSONArray();}
 JSONArray examples(){try{return new JSONArray("[{\"name\":\"Les petits comptes\",\"description\":\"Les dépenses partagées, sans prise de tête. Pour les vacances, les sorties ou la maison.\",\"category\":\"Pratique\",\"demo\":true},{\"name\":\"À table\",\"description\":\"Vos recettes préférées et les idées de repas de la semaine, au même endroit.\",\"category\":\"Maison\",\"demo\":true},{\"name\":\"Mémo\",\"description\":\"Une idée, une liste, une chose à ne pas oublier. Notez-la et retrouvez-la simplement.\",\"category\":\"Pratique\",\"demo\":true},{\"name\":\"Le jardin\",\"description\":\"Un petit compagnon pour vos plantes et leurs soins au quotidien.\",\"category\":\"Loisirs\",\"demo\":true}]");}catch(Exception e){return new JSONArray();}}
 void render(){showingDetail=false;root=col();root.setBackgroundColor(PAPER);root.setOnApplyWindowInsetsListener((view,insets)->{view.setPadding(0,insets.getSystemWindowInsetTop(),0,insets.getSystemWindowInsetBottom());return insets;});setContentView(root);
  LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);head.setPadding(dp(23),dp(17),dp(23),dp(12));ImageView mark=new ImageView(this);mark.setImageResource(R.drawable.ic_cercle);head.addView(mark,new LinearLayout.LayoutParams(dp(37),dp(37)));TextView brand=text("  cercle",29,INK,true);head.addView(brand,new LinearLayout.LayoutParams(0,-2,1));TextView state=badge(demo()?"Aperçu":"Mon store",demo());head.addView(state);root.addView(head);
  ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setClipToPadding(false);content=col();content.setPadding(dp(23),dp(12),dp(23),dp(28));scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  if(selected==0)catalog();else if(selected==1)updates();else account();
  bottom=new LinearLayout(this);bottom.setBackgroundColor(Color.WHITE);bottom.setPadding(dp(12),dp(10),dp(12),dp(10));String[] names={"▦  Découvrir","↻  Mises à jour","◉  Mon Cercle"};for(int i=0;i<names.length;i++){final int tab=i;Button b=button(names[i],false,()->{selected=tab;render();});b.setTextSize(11);b.setBackground(background(i==selected?Color.rgb(235,242,225):Color.WHITE,12,false));b.setContentDescription(names[i].substring(3));bottom.addView(b,new LinearLayout.LayoutParams(0,dp(48),1));}root.addView(bottom,new LinearLayout.LayoutParams(-1,-2));}
 void hero(){LinearLayout hero=col();pad(hero,23);hero.setBackground(background(GREEN,22,false));TextView eyebrow=text(demo()?"BIENVENUE DANS VOTRE CERCLE":"DES CRÉATIONS À PARTAGER",10,LIME,true);eyebrow.setLetterSpacing(.13f);full(hero,eyebrow);gap(hero,15);full(hero,text("De petites applis.\nPour la vraie vie.",29,Color.WHITE,true));gap(hero,12);full(hero,text("Des idées faites maison,\nà portée de main.",14,Color.rgb(210,225,213),false));full(content,hero);gap(content,22);}
 void catalog(){hero();if(demo())notice(content,"Vous explorez un aperçu. Les applications présentées sont des exemples.",true);else if(!networkError.isEmpty())notice(content,networkError,true);
  EditText search=new EditText(this);search.setSingleLine();search.setTextSize(14);search.setHint("Rechercher dans le Cercle…");search.setContentDescription("Rechercher une application");search.setBackground(background(Color.WHITE,13,true));search.setPadding(dp(15),dp(10),dp(15),dp(10));full(content,search);gap(content,15);
  HorizontalScrollView chips=new HorizontalScrollView(this);chips.setHorizontalScrollBarEnabled(false);LinearLayout row=new LinearLayout(this);chips.addView(row);LinkedHashSet<String> categories=new LinkedHashSet<>();categories.add("Tout");for(int i=0;i<apps.length();i++)if(!apps.optJSONObject(i).optString("packageName").equals(getPackageName()))categories.add(apps.optJSONObject(i).optString("category","Pratique"));final String[] current={"Tout"};LinearLayout list=col();
  for(String category:categories){Button b=button(category,false,()->{current[0]=category;for(int j=0;j<row.getChildCount();j++){Button item=(Button)row.getChildAt(j);boolean active=item.getText().toString().equals(category);item.setTextColor(active?Color.WHITE:GREEN);item.setBackground(background(active?GREEN:Color.WHITE,22,!active));}renderList(list,search.getText().toString(),current[0],false);});b.setTextSize(12);b.setMinHeight(dp(40));b.setMinimumHeight(dp(40));if(category.equals("Tout")){b.setTextColor(Color.WHITE);b.setBackground(background(GREEN,22,false));}LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,dp(41));lp.setMargins(0,0,dp(8),0);row.addView(b,lp);}full(content,chips);gap(content,22);TextView title=text("À découvrir",21,INK,true);full(content,title);gap(content,15);full(content,list);renderList(list,"","Tout",false);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){renderList(list,s.toString(),current[0],false);}public void afterTextChanged(Editable e){}});
  gap(content,18);full(content,button(loading?"Actualisation…":"Actualiser le catalogue",false,()->refresh(true)));gap(content,18);TextView note=text("Gratuit · Partagé entre proches",12,MUTED,false);note.setGravity(Gravity.CENTER);full(content,note);}
 boolean needsUpdate(JSONObject app){try{PackageInfo p=Packages.installed(this,app.getString("packageName"));return p!=null&&Packages.version(p)<app.getJSONObject("release").getLong("versionCode");}catch(Exception e){return false;}}
 void renderList(LinearLayout list,String query,String category,boolean updateOnly){list.removeAllViews();int count=0;for(int i=0;i<apps.length();i++){JSONObject app=apps.optJSONObject(i);if(app==null||(!updateOnly&&app.optString("packageName").equals(getPackageName()))||(!category.equals("Tout")&&!category.equals(app.optString("category")))||!(app.optString("name")+" "+app.optString("description")).toLowerCase(Locale.FRENCH).contains(query.toLowerCase(Locale.FRENCH))||(updateOnly&&!needsUpdate(app)))continue;card(list,app,i);count++;}if(count==0){LinearLayout empty=col();pad(empty,25);empty.setBackground(background(Color.WHITE,20,true));full(empty,text(updateOnly?"Tout est à jour.":visibleCount()==0?"Votre Cercle se prépare.":"Aucun résultat pour le moment.",19,INK,true));gap(empty,9);full(empty,text(updateOnly?"Les nouvelles versions apparaîtront ici.":visibleCount()==0?"Votre proche peut maintenant ajouter ses premières applications.":"Essayez avec un autre mot ou une autre catégorie.",14,MUTED,false));full(list,empty);}}
 void card(LinearLayout list,JSONObject app,int index){LinearLayout card=col();pad(card,19);card.setBackground(background(Color.WHITE,20,true));LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);TextView icon=appIcon(app.optString("name"),index);top.addView(icon,new LinearLayout.LayoutParams(dp(53),dp(53)));LinearLayout title=col();title.setPadding(dp(13),0,0,0);full(title,text(app.optString("name"),17,INK,true));gap(title,4);title.addView(badge(app.optString("category","Pratique"),false));top.addView(title,new LinearLayout.LayoutParams(0,-2,1));full(card,top);gap(card,13);TextView description=text(app.optString("description"),14,MUTED,false);description.setMaxLines(3);description.setEllipsize(TextUtils.TruncateAt.END);full(card,description);gap(card,14);LinearLayout footer=new LinearLayout(this);footer.setGravity(Gravity.CENTER_VERTICAL);TextView meta=text(app.optBoolean("demo")?"Gratuite · Exemple":"Gratuite · v"+app.optJSONObject("release").optString("versionName"),12,MUTED,false);footer.addView(meta,new LinearLayout.LayoutParams(0,-2,1));Button b=button(app.optBoolean("demo")?"Voir la fiche":needsUpdate(app)?"Mettre à jour":"Découvrir",false,()->detail(app,index));b.setTextSize(12);footer.addView(b);full(card,footer);full(list,card);gap(list,13);}
 TextView appIcon(String name,int index){int[] colors={Color.rgb(229,237,207),Color.rgb(250,229,212),Color.rgb(220,232,241),Color.rgb(243,224,232)};TextView icon=text(name.isEmpty()?"C":name.substring(0,Math.min(2,name.length())).toUpperCase(Locale.FRENCH),21,INK,true);icon.setGravity(Gravity.CENTER);icon.setBackground(background(colors[Math.abs(index)%colors.length],17,false));return icon;}
 int visibleCount(){int count=0;for(int i=0;i<apps.length();i++)if(!apps.optJSONObject(i).optString("packageName").equals(getPackageName()))count++;return count;}
 void updates(){full(content,text("Un petit coup de neuf.",30,INK,true));gap(content,9);full(content,text("Les dernières versions de vos applications, au même endroit.",15,MUTED,false));gap(content,24);if(demo()){notice(content,"Vous êtes en mode aperçu. Revenez au catalogue pour retrouver les vraies mises à jour.",false);full(content,button("Ouvrir le catalogue",true,this::leavePreview));return;}if(!networkError.isEmpty())notice(content,networkError,true);LinearLayout list=col();full(content,list);renderList(list,"","Tout",true);gap(content,18);full(content,button(loading?"Vérification…":"Vérifier les mises à jour",false,()->refresh(true)));gap(content,12);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)full(content,button("M’avertir des nouveautés",false,()->requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},3)));}
 void leavePreview(){Access.prefs(this).edit().putBoolean("preview",false).apply();apps=new JSONArray();selected=0;networkError="";loadCached();render();refresh(false);}
 void account(){full(content,text("Votre petit Cercle.",30,INK,true));gap(content,10);full(content,text("Des applications gratuites et ouvertes, à partager simplement.",15,MUTED,false));gap(content,25);LinearLayout panel=col();pad(panel,22);panel.setBackground(background(Color.WHITE,20,true));full(panel,text(demo()?"Vous explorez un aperçu.":"Tout est prêt pour découvrir.",21,INK,true));gap(panel,10);full(panel,text("Aucun compte n’est nécessaire. Le catalogue est public et les fichiers sont vérifiés avant installation.",14,MUTED,false));gap(panel,20);full(panel,button(demo()?"Ouvrir le vrai catalogue":"Partager le store",true,()->{if(demo()){leavePreview();return;}Intent share=new Intent(Intent.ACTION_SEND);share.setType("text/plain");share.putExtra(Intent.EXTRA_TEXT,"Retrouve les applications de Cercle ici : "+StoreConfig.page(this));startActivity(Intent.createChooser(share,"Partager Cercle"));}));gap(panel,12);full(panel,button(demo()?"Rester dans l’aperçu":"Explorer le mode aperçu",false,()->{Access.prefs(this).edit().putBoolean("preview",true).apply();apps=examples();selected=0;networkError="";render();}));full(content,panel);gap(content,23);full(content,text("La première installation",20,INK,true));gap(content,10);full(content,text("Android vous demandera d’autoriser Cercle à installer des applications. Un guide apparaîtra au bon moment, puis vous confirmerez chaque installation.",14,MUTED,false));gap(content,20);full(content,text("Des applications gratuites",20,INK,true));gap(content,10);full(content,text("Les fiches peuvent inclure le code source. Cercle n’ajoute ni publicité ni suivi publicitaire.",14,MUTED,false));gap(content,25);full(content,text("Cercle 0.2.0 · Catalogue public",12,MUTED,false));}
 void detail(JSONObject app,int index){showingDetail=true;content.removeAllViews();full(content,button("← Retour au catalogue",false,()->{showingDetail=false;render();}));gap(content,25);TextView icon=appIcon(app.optString("name"),index);content.addView(icon,new LinearLayout.LayoutParams(dp(74),dp(74)));gap(content,20);full(content,text(app.optString("name"),30,INK,true));gap(content,10);content.addView(badge(app.optString("category","Pratique"),false));gap(content,20);full(content,text(app.optString("description"),16,MUTED,false));gap(content,25);if(app.optBoolean("demo")){notice(content,"Cette application est un exemple pour découvrir le store. Votre vrai catalogue sera rempli par votre proche.",true);full(content,button("Ouvrir le catalogue",true,this::leavePreview));return;}JSONObject release=app.optJSONObject("release");full(content,text("Version "+release.optString("versionName")+" · "+String.format(Locale.FRENCH,"%.1f Mo",release.optLong("size")/1048576.0),13,MUTED,false));gap(content,10);full(content,text("Licence : "+app.optString("license","À préciser"),13,MUTED,false));gap(content,22);PackageInfo installed=Packages.installed(this,app.optString("packageName"));if(installed!=null&&Packages.version(installed)>=release.optLong("versionCode")){Intent launch=getPackageManager().getLaunchIntentForPackage(app.optString("packageName"));full(content,button(launch==null?"Application installée":"Ouvrir l’application",true,()->{if(launch!=null)startActivity(launch);else Toast.makeText(this,"L’application est déjà installée.",Toast.LENGTH_SHORT).show();}));}else if(release.optInt("minSdk")>Build.VERSION.SDK_INT)notice(content,"Cette application nécessite une version d’Android plus récente.",true);else full(content,button(installed!=null?"Mettre à jour":"Installer gratuitement",true,()->prepareInstall(app)));
  String source=app.optString("sourceUrl","");if(source.startsWith("https://")){gap(content,12);full(content,button("Voir le code source ↗",false,()->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(source)));}catch(Exception e){alert("Lien indisponible","Aucun navigateur n’a pu ouvrir ce lien.");}}));}gap(content,22);notice(content,"Le fichier et sa signature seront vérifiés avant de laisser Android confirmer l’installation.",false);}
 void handleIntent(Intent intent){intent.setData(null);}
 void refresh(boolean user){if(demo()){if(user)Toast.makeText(this,"L’aperçu est prêt. Retrouvez le vrai catalogue dans Mon Cercle.",Toast.LENGTH_LONG).show();return;}if(loading)return;loading=true;new Thread(()->{try{JSONObject catalog=Api.catalog(this);JSONArray result=catalog.getJSONArray("apps");runOnUiThread(()->{loading=false;apps=result;networkError="";if(!showingDetail)render();});}catch(Exception e){runOnUiThread(()->{loading=false;networkError=friendly(e);if(!showingDetail)render();if(user)alert("Actualisation impossible",networkError);});}},"cercle-catalog").start();}
 String friendly(Exception e){if(e instanceof java.net.UnknownHostException||e instanceof java.net.ConnectException||e instanceof java.net.SocketTimeoutException)return "Le store est injoignable. Vérifiez votre connexion puis réessayez.";String m=e.getMessage();return m==null?"Une erreur est survenue. Réessayez dans un instant.":m;}
 void prepareInstall(JSONObject app){if(!getPackageManager().canRequestPackageInstalls()){new AlertDialog.Builder(this).setTitle("Une autorisation, une seule fois.").setMessage("Android a besoin de votre accord pour installer les applications de Cercle.\n\nAppuyez sur Continuer, activez l’autorisation, puis revenez ici.").setNegativeButton("Plus tard",null).setPositiveButton("Continuer",(d,w)->{pendingInstall=app;try{startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getPackageName())));}catch(Exception e){pendingInstall=null;alert("Réglage indisponible","Ouvrez les réglages Android de Cercle et autorisez l’installation d’applications.");}}).show();return;}download(app);}
 void download(JSONObject app){ProgressDialog progress=new ProgressDialog(this);progress.setTitle("Préparation de l’application");progress.setMessage(app.optString("name"));progress.setProgressStyle(ProgressDialog.STYLE_HORIZONTAL);progress.setMax(100);progress.setCancelable(false);AtomicBoolean cancel=new AtomicBoolean(false);progress.setButton(ProgressDialog.BUTTON_NEGATIVE,"Annuler",(d,w)->cancel.set(true));progress.show();new Thread(()->{File file=null;try{file=Packages.download(this,app,percent->{if(cancel.get())throw new RuntimeException("Téléchargement annulé.");runOnUiThread(()->progress.setProgress(percent));});if(cancel.get())throw new IOException("Téléchargement annulé.");final File ready=file;runOnUiThread(()->{progress.dismiss();try{install(ready,app);}catch(Exception e){ready.delete();alert("Installation impossible",friendly(e));}});}catch(Exception e){if(file!=null)file.delete();runOnUiThread(()->{progress.dismiss();alert("L’application n’a pas été installée",friendly(e));});}},"cercle-download").start();}
 void install(File file,JSONObject app)throws Exception{if(isFinishing()){file.delete();return;}PackageInstaller installer=getPackageManager().getPackageInstaller();PackageInstaller.SessionParams params=new PackageInstaller.SessionParams(PackageInstaller.SessionParams.MODE_FULL_INSTALL);params.setAppPackageName(app.getString("packageName"));params.setSize(file.length());if(Build.VERSION.SDK_INT>=31)params.setRequireUserAction(PackageInstaller.SessionParams.USER_ACTION_REQUIRED);int id=installer.createSession(params);boolean committed=false;try(PackageInstaller.Session session=installer.openSession(id)){try(InputStream in=new FileInputStream(file);OutputStream out=session.openWrite("base.apk",0,file.length())){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);session.fsync(out);}Intent callback=new Intent(this,InstallResultActivity.class).setAction("fr.zachiran.cercle.INSTALL_RESULT");int flags=PendingIntent.FLAG_UPDATE_CURRENT;if(Build.VERSION.SDK_INT>=31)flags|=PendingIntent.FLAG_MUTABLE;PendingIntent pending=PendingIntent.getActivity(this,id,callback,flags);session.commit(pending.getIntentSender());committed=true;}finally{file.delete();if(!committed)installer.abandonSession(id);}}
 @Override public void onBackPressed(){if(showingDetail||selected!=0){selected=0;render();}else super.onBackPressed();}
